# Generated by Claudian.
"""Skill: mute / unmute system audio."""

import re

from ai.response_generator import ResponseGenerator
from automation.system_control import mute_audio, unmute_audio
from multitasking.async_executor import run_in_thread
from skills._base import Skill, SkillMatch, SkillResult

_UNMUTE_RE = re.compile(r"\bunmute\b|turn\s+(?:the\s+)?sound\s+on")
_MUTE_RE = re.compile(
    r"\bmute\b|silence\s+(the\s+)?(mac|computer|sound|audio)"
    r"|turn\s+(?:the\s+)?sound\s+off"
)


class MuteSkill(Skill):
    name = "mute"
    description = "Mute or unmute system audio"
    priority = 15

    def __init__(self):
        self._responses = ResponseGenerator()

    def match(self, text: str) -> SkillMatch | None:
        low = text.lower()
        if _UNMUTE_RE.search(low):
            return SkillMatch(confidence=0.95, entities={"action": "unmute"})
        if _MUTE_RE.search(low):
            return SkillMatch(confidence=0.95, entities={"action": "mute"})
        return None

    async def run(self, text: str, entities: dict) -> SkillResult:
        action = entities.get("action", "mute").lower()
        if action == "unmute":
            ok = await run_in_thread(unmute_audio)
            return SkillResult(
                text="Unmuted." if ok else self._responses.action_failed("unmute")
            )
        ok = await run_in_thread(mute_audio)
        return SkillResult(
            text="Muted." if ok else self._responses.action_failed("mute")
        )
